module FPAdd32(
  input  [31:0] io_a, 
  input  [31:0] io_b, 
  input         io_sub, 
  output [31:0] io_result 
);

FP32AddIP FP32AddIP_instance (
  .s_axis_a_tvalid(1'b1),                  // input wire s_axis_a_tvalid
  .s_axis_a_tdata(io_a),                    // input wire [31 : 0] s_axis_a_tdata
  .s_axis_b_tvalid(1'b1),                  // input wire s_axis_b_tvalid
  .s_axis_b_tdata(io_b),                    // input wire [31 : 0] s_axis_b_tdata
  .s_axis_operation_tvalid(),  // input wire s_axis_operation_tvalid
  .s_axis_operation_tdata({7'b0, io_sub}),    // input wire [7 : 0] s_axis_operation_tdata
  .m_axis_result_tvalid(),        // output wire m_axis_result_tvalid
  .m_axis_result_tdata(io_result)          // output wire [31 : 0] m_axis_result_tdata
);

endmodule


module FPMult32(
  input         clock,
  input  [31:0] io_a, 
  input  [31:0] io_b, 
  output [31:0] io_result 
);


FP32MulIP FP32MulIP_instance (
  .aclk(clock),                                  // input wire aclk
  .s_axis_a_tvalid(1'b1),            // input wire s_axis_a_tvalid
  .s_axis_a_tready(),            // output wire s_axis_a_tready
  .s_axis_a_tdata(io_a),              // input wire [31 : 0] s_axis_a_tdata
  .s_axis_b_tvalid(1'b1),            // input wire s_axis_b_tvalid
  .s_axis_b_tready(),            // output wire s_axis_b_tready
  .s_axis_b_tdata(io_b),              // input wire [31 : 0] s_axis_b_tdata
  .m_axis_result_tvalid(),  // output wire m_axis_result_tvalid
  .m_axis_result_tdata(io_result)    // output wire [31 : 0] m_axis_result_tdata
);

endmodule


