module SramAddrGen(
  input  [17:0] CurAddr, 
  input  [7:0]  Len, 
  input  [2:0]  Size, 
  input  [1:0]  Burst, 
  output [17:0] NextAddr 
);
  wire [11:0] iCurAddr = CurAddr[11:0]; 
  wire [1:0] _iSize_T_3 = 3'h2 == Size ? 2'h2 : {{1'd0}, 3'h1 == Size}; 
  wire [1:0] _iSize_T_5 = 3'h3 == Size ? 2'h3 : _iSize_T_3; 
  wire [2:0] _iSize_T_7 = 3'h4 == Size ? 3'h4 : {{1'd0}, _iSize_T_5}; 
  wire [2:0] _iSize_T_9 = 3'h5 == Size ? 3'h5 : _iSize_T_7; 
  wire [2:0] _iSize_T_11 = 3'h6 == Size ? 3'h6 : _iSize_T_9; 
  wire [2:0] iSize = 3'h7 == Size ? 3'h7 : _iSize_T_11; 
  wire [11:0] wordAddress = iCurAddr >> iSize; 
  wire [11:0] _incrNextAddr_T_1 = wordAddress + 12'h1; 
  wire [18:0] _GEN_1 = {{7'd0}, _incrNextAddr_T_1}; 
  wire [18:0] incrNextAddr = _GEN_1 << iSize; 
  wire [3:0] _wrapBound_T_3 = ~Len[3:0]; 
  wire [3:0] _wrapBound_T_4 = wordAddress[3:0] & _wrapBound_T_3; 
  wire [11:0] _wrapBound_T_5 = {wordAddress[11:4],_wrapBound_T_4}; 
  wire [18:0] _GEN_2 = {{7'd0}, _wrapBound_T_5}; 
  wire [18:0] wrapBound = _GEN_2 << iSize; 
  wire [4:0] _totSize_T_1 = Len[3:0] + 4'h1; 
  wire [11:0] _GEN_3 = {{7'd0}, _totSize_T_1}; 
  wire [11:0] totSize = _GEN_3 << iSize; 
  wire [18:0] _GEN_0 = {{7'd0}, totSize}; 
  wire [18:0] _wrapNextAddr_T_1 = wrapBound + _GEN_0; 
  wire [18:0] wrapNextAddr = incrNextAddr == _wrapNextAddr_T_1 ? wrapBound : incrNextAddr; 
  wire [18:0] _iNextAddr_T_3 = 2'h1 == Burst ? incrNextAddr : {{1'd0}, CurAddr}; 
  wire [18:0] _iNextAddr_T_5 = 2'h2 == Burst ? wrapNextAddr : _iNextAddr_T_3; 
  wire [11:0] iNextAddr = _iNextAddr_T_5[11:0]; 
  assign NextAddr = {CurAddr[17:12],iNextAddr}; 
endmodule
module WriteEngine(
  input          aclk, 
  input          aresetn, 
  output         s_axi_aw_ready, 
  input          s_axi_aw_valid, 
