  input          s_axi_b_ready, 
  output         s_axi_b_valid, 
  output [5:0]   s_axi_b_bits_id, 
  input          ready, 
  output         valid, 
  output [17:0]  addr, 
  output [127:0] data, 
  output [15:0]  strb 
);
`ifdef RANDOMIZE_REG_INIT
  reg [31:0] _RAND_0;
  reg [31:0] _RAND_1;
  reg [31:0] _RAND_2;
  reg [31:0] _RAND_3;
