  wire [7:0] NextAddr_m_Len; 
  wire [2:0] NextAddr_m_Size; 
  wire [1:0] NextAddr_m_Burst; 
  wire [17:0] NextAddr_m_NextAddr; 
  wire  reset = ~aresetn; 
  reg [1:0] state; 
  reg [7:0] spad_needed_len; 
  reg [1:0] wBurst; 
  reg [2:0] wSize; 
  reg [5:0] iBID; 
  reg [17:0] iAddr; 
  wire [17:0] NextAddr = NextAddr_m_NextAddr; 
  wire [17:0] _GEN_12 = s_axi_w_valid ? NextAddr : iAddr; 
  wire [1:0] _GEN_13 = s_axi_w_bits_last & s_axi_w_valid ? 2'h3 : state; 
  wire [17:0] _GEN_14 = s_axi_w_bits_last & s_axi_w_valid ? iAddr : _GEN_12; 
  wire [1:0] _GEN_19 = s_axi_b_ready ? 2'h0 : state; 
  SramAddrGen NextAddr_m ( 
    .CurAddr(NextAddr_m_CurAddr),
    .Len(NextAddr_m_Len),
    .Size(NextAddr_m_Size),
    .Burst(NextAddr_m_Burst),
    .NextAddr(NextAddr_m_NextAddr)
  );
  assign s_axi_aw_ready = state == 2'h0; 
  assign s_axi_w_ready = state == 2'h2; 
  assign s_axi_b_valid = state == 2'h3; 
