  assign NextAddr_m_Len = spad_needed_len; 
  assign NextAddr_m_Size = wSize; 
  assign NextAddr_m_Burst = wBurst; 
  always @(posedge aclk or posedge reset) begin
    if (reset) begin 
      state <= 2'h0; 
    end else if (2'h0 == state) begin 
      if (s_axi_aw_valid) begin 
        state <= 2'h2; 
      end
    end else if (2'h1 == state) begin 
      if (ready) begin 
        state <= 2'h2; 
      end
    end else if (2'h2 == state) begin 
      if (~ready) begin
        state <= 2'h1;
      end else begin
        state <= _GEN_13;
      end
    end else if (2'h3 == state) begin 
      state <= _GEN_19;
    end
  end
  always @(posedge aclk or posedge reset) begin
    if (reset) begin 
      spad_needed_len <= 8'h0; 
    end else if (2'h0 == state) begin 
      if (s_axi_aw_valid) begin
        spad_needed_len <= s_axi_aw_bits_len;
      end
    end
