module TileStateCtrl(
  input        clock,
  input        reset,
  input        io_cfgStartReq, 
  input        io_cfgDoneIn, 
  input        io_exeStartReq, 
  input  [3:0] io_exeIobEnReq, 
  input  [3:0] io_exeTileEnReq, 
  input  [4:0] io_exeDoneIn, 
  output       io_cfgDone, 
  output       io_exeDone, 
  output       io_exeStartP, 
  output [3:0] io_exeIobEn, 
  output       io_exeEn 
);
`ifdef RANDOMIZE_REG_INIT
  reg [31:0] _RAND_0;
  reg [31:0] _RAND_1;
  reg [31:0] _RAND_2;
  reg [31:0] _RAND_3;
`endif // RANDOMIZE_REG_INIT
  reg [3:0] exeIobEnReg; 
  reg [3:0] exeRelatedTileReg; 
  reg [2:0] tile_state; 
  reg [2:0] prev_state; 
  wire [3:0] _GEN_1 = io_exeStartReq ? io_exeIobEnReq : exeIobEnReg; 
  wire [3:0] _GEN_2 = io_exeStartReq ? io_exeTileEnReq : exeRelatedTileReg; 
  wire [2:0] _GEN_6 = io_exeStartReq ? 3'h3 : tile_state; 
  wire [2:0] _GEN_7 = io_cfgDoneIn ? 3'h0 : _GEN_6; 
  wire [3:0] _GEN_8 = io_cfgDoneIn ? exeIobEnReg : _GEN_1; 
  wire [3:0] _GEN_9 = io_cfgDoneIn ? exeRelatedTileReg : _GEN_2; 
  wire [3:0] _GEN_10 = io_cfgDoneIn & io_exeStartReq ? io_exeIobEnReq : _GEN_8; 
  wire [3:0] _GEN_11 = io_cfgDoneIn & io_exeStartReq ? io_exeTileEnReq : _GEN_9; 
  wire [2:0] _GEN_12 = io_cfgDoneIn & io_exeStartReq ? 3'h4 : _GEN_7; 
  wire [2:0] _GEN_13 = io_cfgDoneIn ? 3'h4 : tile_state; 
  wire [4:0] _GEN_28 = {{1'd0}, exeRelatedTileReg}; 
  wire [4:0] _T_6 = io_exeDoneIn & _GEN_28; 
  wire [2:0] _GEN_14 = _T_6 != _GEN_28 ? 3'h5 : tile_state; 
  wire [2:0] _GEN_15 = _T_6 == _GEN_28 ? 3'h0 : tile_state; 
  wire [2:0] _GEN_16 = 3'h5 == tile_state ? _GEN_15 : tile_state; 
  wire [2:0] _GEN_17 = 3'h4 == tile_state ? _GEN_14 : _GEN_16; 
  wire [2:0] _GEN_18 = 3'h3 == tile_state ? _GEN_13 : _GEN_17; 
  wire  _io_exeStartP_T_5 = prev_state == 3'h3 | prev_state == 3'h2 | prev_state == 3'h0; 
  assign io_cfgDone = tile_state != 3'h1 & tile_state != 3'h2; 
  assign io_exeDone = tile_state != 3'h3 & tile_state != 3'h4 & tile_state != 3'h5; 
  assign io_exeStartP = tile_state == 3'h4 & _io_exeStartP_T_5; 
  assign io_exeIobEn = exeIobEnReg; 
  assign io_exeEn = tile_state == 3'h5; 
  always @(posedge clock) begin
    if (reset) begin 
      exeIobEnReg <= 4'h0; 
    end else if (3'h0 == tile_state) begin 
      if (!(io_cfgStartReq)) begin 
        if (io_exeStartReq) begin 
          exeIobEnReg <= io_exeIobEnReq; 
        end
      end
    end else if (!(3'h1 == tile_state)) begin 
      if (3'h2 == tile_state) begin 
        exeIobEnReg <= _GEN_10;
      end
    end
    if (reset) begin 
      exeRelatedTileReg <= 4'h0; 
    end else if (3'h0 == tile_state) begin 
      if (!(io_cfgStartReq)) begin 
        if (io_exeStartReq) begin 
          exeRelatedTileReg <= io_exeTileEnReq; 
        end
      end
    end else if (!(3'h1 == tile_state)) begin 
      if (3'h2 == tile_state) begin 
        exeRelatedTileReg <= _GEN_11;
      end
    end
    if (reset) begin 
      tile_state <= 3'h0; 
    end else if (3'h0 == tile_state) begin 
      if (io_cfgStartReq) begin 
        tile_state <= 3'h1; 
      end else if (io_exeStartReq) begin 
        tile_state <= 3'h4; 
      end
    end else if (3'h1 == tile_state) begin 
      tile_state <= 3'h2; 
    end else if (3'h2 == tile_state) begin 
      tile_state <= _GEN_12;
    end else begin
      tile_state <= _GEN_18;
    end
    prev_state <= tile_state; 
  end
