  integer initvar;
`endif
`ifndef SYNTHESIS
`ifdef FIRRTL_BEFORE_INITIAL
`FIRRTL_BEFORE_INITIAL
`endif
initial begin
  `ifdef RANDOMIZE
    `ifdef INIT_RANDOM
      `INIT_RANDOM
    `endif
    `ifndef VERILATOR
      `ifdef RANDOMIZE_DELAY
        #`RANDOMIZE_DELAY begin end
      `else
        #0.002 begin end
      `endif
    `endif
`ifdef RANDOMIZE_REG_INIT
  _RAND_0 = {1{`RANDOM}};
  exeIobEnReg = _RAND_0[3:0];
  _RAND_1 = {1{`RANDOM}};
  exeRelatedTileReg = _RAND_1[3:0];
  _RAND_2 = {1{`RANDOM}};
  tile_state = _RAND_2[2:0];
  _RAND_3 = {1{`RANDOM}};
  prev_state = _RAND_3[2:0];
`endif // RANDOMIZE_REG_INIT
